#!/usr/bin/env python
"""props_lib.paperbomb_art - the printed artwork of SM_PaperBomb, drawn from scratch.

This module DRAWS the tag.  It owns every mark on the paper: the aged ground, the red
rules and their corner flourishes, the broken dry-brush ring, the flame emblem, the two
seal boxes and every typeset character.  It produces float layers at any resolution -
base colour, ink coverage, ink load, roughness, relief, masks - which the material module
turns into M_PaperBomb and the bake turns into T_PaperBomb_BC/_ORM/_N/_M.

    ORIGINALITY.  Nothing here is sampled, traced or derived from an image.  Every shape
    is generated by the code in this file: the paper is value noise, the rules and the
    ring are brush strokes swept along paths this module computes, the flame emblem and
    the seal device are curves this module defines, and every character is typeset by
    Blender from References/Fonts/MasaFont-Bold.ttf (SIL OFL 1.1).  The only file this
    module ever opens is that .ttf.  References/PaperBomb/paperbomb_guide*.png were read
    once, by the study's measurement scripts, to recover a table of proportions; this
    module has no knowledge of them and ``art_provenance()`` states that for the build
    report.  ``FORBIDDEN_INPUT_FRAGMENTS`` exists so a build gate can assert it.

    HEADLESS ONLY.  bpy is used for one thing: pulling glyph outlines out of the font.

        "C:/Program Files/Blender Foundation/Blender 5.2/blender.exe" -b \
            --factory-startup --python Scripts/props/props_lib/paperbomb_art.py -- \
            --out WorkFiles/paperbomb/art --ppmm 12.923


THE TEXT CONFIG
---------------
``TEXT`` below is the ONLY place any string lives.  Six slots, each one word:

    slot           string   reading         placed
    centre         U+7206   baku            dead centre, over the ring, the biggest mark
    upper_left     U+706B U+9041 U+8853     katon-jutsu, left of the emblem, 3 cells
    upper_right    U+7206 U+708E U+9663     baku-en-jin, right of the emblem, 3 cells
    lower_right    U+713C U+5C3D            shoujin, lower right, 2 cells
    lower_centre   U+77AC U+696D            (the user's own compound), lower centre
    small_seal     U+706B U+9053            kadou, inside the small seal box, in red

Every column is laid out CELL BY CELL, top to bottom: each character is typeset on its
own, its ink bounding box is centred in its cell, and the cell centres come from
``LAYOUT``.  Nothing is rotated and no horizontal string is ever turned on its side.

Swapping a string is a one-word edit in ``TEXT``.  A missing glyph is a hard failure -
``MissingGlyph`` - never a fallback box, never a hand-drawn approximation.  The strings
are written as escapes so the file is safe to open in any editor and nothing ever prints
a raw kanji to a cp1252 console; the logs print slot names and U+XXXX codepoints.

The lower-centre compound is EXACTLY as the user wrote it.  It is not a standard
compound and the "corrected" alternative was offered and declined.  Do not fix it.


HOW A MARK IS MADE
------------------
Three primitives, and everything on the tag is one of them.

``brush_stroke``    sweeps a brush along a path.  The path is resampled to a fixed step,
                    each segment is rasterised into its own little window, and every
                    pixel comes out carrying (coverage, s, u): how far along the stroke it
                    is and how far across it, normalised.  Having (s, u) per pixel is what
                    makes the brush a brush - the dry-brush streaks are noise that is slow
                    in s and fast in u, so the bare-paper streaks necessarily run ALONG
                    the stroke and widen where the brush lifted, instead of looking like
                    holes punched in a vector ring.  Width is a per-vertex array, so a
                    5:1 swell is free; a constant width is never used anywhere.

``fill_path``       scanline-fills closed polygons (nonzero winding, 4x row supersampling
                    and exact fractional x coverage).  Glyph outlines, the seal panel,
                    the lozenges and the flame tongues' solid heart all go through it.

``Ink``             a two-field layer: ``a`` opacity and ``d`` load.  Load 1 is a fully
                    charged brush (the darkest, wettest value); load 0 is a starved one
                    that sits pale and grey-brown over the paper.  Colour is resolved at
                    composite time as lerp(dry, wet, d), so the same geometry reads wet or
                    dry without redrawing it.

On top of those: ``ink_bleed`` wicks a soft ragged halo into the fibre (stronger across
the sheet than along it, and only under heavy strokes), and ``cockle`` pulls the sheet
down where wet ink dried, which is the only reason the print shows in the normal map.


WHAT COMES OUT
--------------
``TagArt`` (see the dataclass) carries, all float32 and all the same (H, W):

    base_colour   (H, W, 3) LINEAR albedo - paper, ink, seals, wear.  The map the BC bake
                  wants.  Values stay inside the dielectric band; nothing is 0 or 1.
    paper_rgb     the aged ground alone, no ink - useful for a blank variant
    ink_black / ink_red   ``Ink`` layers, opacity and load, if the material wants to
                  recolour or animate them
    roughness     per-pixel, paper 0.86 / ink 0.72 with the dry values above them
    relief        signed height in MILLIMETRES for the normal bake (fibre, cockling,
                  creases, thumb dents).  Curl, folds and the dog-ear are GEOMETRY and are
                  deliberately absent here.
    card_mask     1 inside the trimmed outline (clipped corners, torn bottom, edge nick)
    fringe        the torn edge's fibre fringe -> T_PaperBomb_M red
    scorch        0 at the Fuse socket rising to 1 at the far end -> T_PaperBomb_M green
    ink_mask      max(red, black) opacity -> T_PaperBomb_M blue
    outline_mm    the trimmed outline as a polyline in card millimetres, so the mesh is
                  cut to the same edge the texture is painted to

``build_front`` and ``build_back`` return one each.  The back is blank aged paper - its
own grain, the same creases and thumbing seen from behind - plus a faint mirrored
show-through of the front print, because 80 g/m2 kozo is translucent.


GATES, AND HOW THE ORIGINALITY CLAIM IS PROVED
----------------------------------------------
``no_guide_access()`` is a context manager that replaces ``open`` for the duration of a
build and raises ``GuideAccess`` if anything touches a path under References/PaperBomb.
The CLI draws inside it and records what WAS opened - one file, the .ttf - and
``art_provenance()`` puts that list in the report.  Grepping this file for the guide's
name does not prove anything (the list of forbidden fragments matches itself); running
inside the guard does.

``font_codepoints()`` reads the .ttf's own cmap.  Blender will happily typeset a
character the font lacks - FreeType returns glyph 0 and ``to_curve`` gives you the
.notdef box's outline, which would ship as a fabricated character with nothing
complaining - so coverage is decided from the font binary before anything is drawn and
``MissingGlyph`` stops the build.  ``verify_font_coverage()`` runs that over ``TEXT``.

``measure_ring()`` re-measures the study's two ring numbers on what was actually drawn:
angular presence and area fill.  High presence with low fill is a dry brush lap; high
presence with high fill is a drawn annulus, and low presence is a broken circle.  The
current build: presence 0.97 against the guide's 0.972, fill 0.113 against 0.152.

``card_outline_mm()`` is the one authority for the trimmed edge, so the mesh and the
texture are cut to the same line, and every deviation on it goes INWARD - the card
never leaves its 70.0 x 162.29 mm box.

WHERE THIS DEPARTS FROM THE STUDY, AND WHY
------------------------------------------
The study's layout table was measured off a guide whose centre character is TALL (ink
50.4 x 62.4 mm, aspect 0.81).  MasaFont's U+7206 is the opposite, wide and short (ink
0.956 x 0.789 of its em), so a few numbers had to move or the composition breaks.  Each
one is marked OURS at its constant with the reason:

    centre em         67.1 -> 55.0 mm   at 67.1 the ink is 64 mm wide on a 70 mm card
    ring outer        55.0 x 68.8 -> 57.5 x 65.5 mm   h/w 1.256 -> 1.14, to fit that glyph
    lower-right cells lifted 0.012 H    U+5C3D's foot was landing on the small seal
    small-seal em     7.5 -> 6.0 mm     U+9053 is 0.95 em wide; 7.1 mm in a 7.5 mm opening
    rule weight       0.90 -> 1.00 mm   and the ring 0.8-3.8 -> 1.1-4.7 mm, by looking
    tail ornament     dropped           the column reaches 145 mm and the rule is at 148.6

Everything else is the study's number.

FRAME AND UNITS
---------------
Card fractions (x from the left edge of the printed face seen from +Z, y from the top)
exactly as References/PaperBomb/PAPERBOMB_STUDY.md section 5 states them; millimetres on
a 70.0 x 162.29 mm card; pixels at ``ppmm``.  Row 0 of every array is the TOP of the tag.
The study's frame conversion, for whoever places the sockets:

    X_mm = (0.5 - y_frac) * 162.29     Y_mm = (0.5 - x_frac) * 70.0

Authority: References/PaperBomb/PAPERBOMB_STUDY.md sections 5 (layout), 6 (colour and
roughness) and 7 (texture plan).  Style: References/Shuriken/style_reference/
STYLE_TARGET.md and the docstring of Scripts/shuriken/shuriken_lib/material.py - worn,
thumbed, grubby at the edges, wear carried by texture and never by clean noise.

The pack's own rule applies here too: gallery images render from BAKED maps only.  This
module is a bake source, not a renderer.
"""

from __future__ import annotations

import argparse
import json
import math
import os
import struct
import sys
import zlib
from dataclasses import dataclass, field
from typing import Iterable, Sequence

import numpy as np

LIB_VERSION = "1.0.0"


# ===========================================================================
# 1.  The text config - the only place any string lives
# ===========================================================================

TEXT = (
    ("centre",       "\u7206"),                # U+7206
    ("upper_left",   "\u706b\u9041\u8853"),    # U+706B U+9041 U+8853
    ("upper_right",  "\u7206\u708e\u9663"),    # U+7206 U+708E U+9663
    ("lower_right",  "\u713c\u5c3d"),          # U+713C U+5C3D
    ("lower_centre", "\u77ac\u696d"),          # U+77AC U+696D  (as the user wrote it)
    ("small_seal",   "\u706b\u9053"),          # U+706B U+9053
)

PROJECT_ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "..", ".."))
FONT_PRIMARY = os.path.join(PROJECT_ROOT, "References", "Fonts", "MasaFont-Bold.ttf")
FONT_FALLBACK = os.path.join(PROJECT_ROOT, "References", "Fonts", "YujiBoku-Regular.ttf")

#: A build gate may assert that none of these appear in this module's resolved inputs.
FORBIDDEN_INPUT_FRAGMENTS = ("paperbomb_guide", "References/PaperBomb", "References\\PaperBomb")

#: No franchise vocabulary is permitted in any name this module emits.
DENY_SUBSTRINGS = (
    "naruto", "kibaku", "kibakufuda", "uzumaki", "konoha", "shippuden", "boruto",
    "akatsuki", "hidden leaf", "explosive tag", "exploding tag",
)


class MissingGlyph(RuntimeError):
    """A configured character has no glyph in the font.  Never improvise one."""


def text_config() -> dict:
    """The text config as data, for the build report."""
    out = []
    for slot, s in TEXT:
        out.append({
            "slot": slot,
            "chars": len(s),
            "codepoints": ["U+%04X" % ord(c) for c in s],
            "font": os.path.basename(FONT_PRIMARY),
        })
    return {"slots": out, "font": FONT_PRIMARY, "fallback_font": FONT_FALLBACK}


class GuideAccess(RuntimeError):
    """Something tried to open a guide image while drawing.  It must never happen."""


class no_guide_access:
    """Context manager that makes the guide-free claim testable rather than asserted.

    While it is active, any attempt to open a path containing one of
    ``FORBIDDEN_INPUT_FRAGMENTS`` raises ``GuideAccess``.  The build script wraps the
    art in it and puts the result in the report, so "no pixel of the reference images
    is in this product" is a thing the build PROVES on every run instead of a sentence
    somebody wrote once.  Grepping this file for the fragments does not prove it - the
    fragment list itself matches - but running inside this guard does.
    """

    def __init__(self, fragments: Sequence[str] = FORBIDDEN_INPUT_FRAGMENTS):
        self.fragments = tuple(f.lower().replace("\\", "/") for f in fragments)
        self._open = None
        self.opened: list[str] = []

    def _check(self, path) -> None:
        try:
            s = os.fspath(path)
        except TypeError:
            return
        if not isinstance(s, str):
            s = s.decode("utf8", "replace")
        low = s.lower().replace("\\", "/")
        for frag in self.fragments:
            if frag in low:
                raise GuideAccess(
                    "paperbomb_art tried to open %r, which is a layout reference.  The "
                    "artwork is drawn, not sampled, so nothing here may read it." % s)
        self.opened.append(s)

    def __enter__(self):
        import builtins
        self._open = builtins.open
        guard = self

        def _guarded(file, *a, **kw):
            guard._check(file)
            return guard._open(file, *a, **kw)

        builtins.open = _guarded
        # ...AND THE SAME DOOR UNDER ANOTHER NAME.  ``io.open`` IS ``builtins.open`` -
        # the same function object - but ``import io; io.open(guide)`` resolves the
        # attribute on the ``io`` module, not on ``builtins``, so patching ``builtins``
        # alone leaves it wide open.  The round-1 independent audit found this hole and
        # it is one line to close.  ``io.open_code`` is the other reader on that module
        # and takes the same treatment.
        import io as _io
        self._io = _io
        self._io_open = getattr(_io, "open", None)
        self._io_open_code = getattr(_io, "open_code", None)
        if self._io_open is not None:
            _io.open = _guarded
        if self._io_open_code is not None:
            def _guarded_code(path):
                guard._check(path)
                return guard._io_open_code(path)
            _io.open_code = _guarded_code
        # ...AND THE OTHER DOOR.  An independent pass pointed out that patching
        # ``builtins.open`` alone leaves ``bpy.data.images.load`` open, and demonstrated
        # it loading the guide from inside an active guard.  It is harmless today -
        # ``no_image_loads()`` below proves this module contains zero image loads of any
        # API - but a guard that only covers the route nobody would take is not a guard.
        # ``bpy.data.images`` is an immutable ``bpy_prop_collection`` and cannot be
        # patched on the instance or the type, so the guard swaps ``bpy.data`` itself
        # for a thin forwarding proxy whose ``images`` is wrapped.  Everything else on
        # ``bpy.data`` is passed straight through, and the real object goes back on exit.
        self._bpy = None
        self._data = None
        try:
            import bpy                                            # noqa: F401
            real = bpy.data

            class _Images:
                def __init__(self, inner):
                    self._inner = inner

                def load(self, filepath, *a, **kw):
                    guard._check(filepath)
                    return self._inner.load(filepath, *a, **kw)

                def __getattr__(self, name):
                    return getattr(self._inner, name)

                def __getitem__(self, k):
                    return self._inner[k]

                def __iter__(self):
                    return iter(self._inner)

                def __len__(self):
                    return len(self._inner)

            class _Data:
                # NO class attribute for ``images``: __getattr__ only runs when normal
                # lookup fails, so declaring it here would shadow the guard.
                def __getattr__(self, name):
                    if name == "images":
                        return _Images(real.images)
                    return getattr(real, name)

            self._bpy = bpy
            self._data = real
            bpy.data = _Data()
        except Exception:                                # pragma: no cover - no bpy
            self._bpy = None
        return self

    def __exit__(self, *exc):
        import builtins
        if self._open is not None:
            builtins.open = self._open
        if getattr(self, "_io", None) is not None:
            if self._io_open is not None:
                self._io.open = self._io_open
            if self._io_open_code is not None:
                self._io.open_code = self._io_open_code
        if getattr(self, "_bpy", None) is not None:
            self._bpy.data = self._data
        return False


#: every way a Python module could read pixels off a file.  ``no_image_loads`` fails on
#: any of them appearing in this module's own source, which is the STATIC half of the
#: guide-free proof: ``no_guide_access`` blocks the routes at run time, this proves the
#: routes are not there to block.  An independent pass found the runtime guard covered
#: only ``builtins.open``; both halves exist now.
FORBIDDEN_IMAGE_CALLS = ("images.load", "image.open", "imread", "imload", "np.load",
                         "numpy.load", "cv2.imread", "plt.imread", "imageio.",
                         "PIL.Image", "Image.open", "load_image", "image.load")


def no_image_loads(path: str | None = None) -> dict:
    """Static proof that this module cannot read pixels off any file at all.

    Parses its own source and reports every call whose dotted name matches
    ``FORBIDDEN_IMAGE_CALLS``, plus every string literal containing a forbidden input
    fragment.  Both lists must be empty.  This is a build gate; see
    ``build_paper_bomb.collect_gates``.
    """
    import ast
    src_path = path or __file__
    with open(src_path, "r", encoding="utf-8") as fh:
        src = fh.read()
    tree = ast.parse(src, filename=src_path)

    def dotted(node):
        bits = []
        while isinstance(node, ast.Attribute):
            bits.append(node.attr)
            node = node.value
        if isinstance(node, ast.Name):
            bits.append(node.id)
        return ".".join(reversed(bits))

    calls: list[str] = []
    for n in ast.walk(tree):
        if isinstance(n, ast.Call):
            name = dotted(n.func)
            low = name.lower()
            for frag in FORBIDDEN_IMAGE_CALLS:
                if frag.lower() in low:
                    calls.append("%s:%d %s" % (os.path.basename(src_path),
                                               getattr(n, "lineno", 0), name))
                    break
    literals: list[str] = []
    for n in ast.walk(tree):
        if isinstance(n, ast.Constant) and isinstance(n.value, str):
            low = n.value.lower().replace("\\", "/")
            # the fragment list itself lives in this file; a literal only counts when it
            # looks like a PATH to a guide rather than the guard's own vocabulary
            if "references/paperbomb/" in low and low.endswith(".png"):
                literals.append("%s:%d %r" % (os.path.basename(src_path),
                                              getattr(n, "lineno", 0), n.value))
    return {
        "source": os.path.basename(src_path),
        "image_load_calls": calls,
        "guide_path_literals": literals,
        "passed": not calls and not literals,
        "checked_for": list(FORBIDDEN_IMAGE_CALLS),
    }


def art_provenance(opened: Sequence[str] | None = None) -> dict:
    """What this module read in order to draw.  Goes in the build report verbatim."""
    return {
        "module": "props_lib.paperbomb_art " + LIB_VERSION,
        "files_the_module_may_open": [FONT_PRIMARY, FONT_FALLBACK],
        "files_actually_opened": sorted(set(opened)) if opened is not None else None,
        "guide_images_opened": [],
        "every_shape": "generated by this module: value noise, swept brush strokes, "
                       "scanline-filled curves this module defines, and glyph outlines "
                       "typeset by Blender from the licensed font",
        "nothing_sampled_from_any_image": True,
        "forbidden_input_fragments": list(FORBIDDEN_INPUT_FRAGMENTS),
        "how_this_is_proved": "run the build inside props_lib.paperbomb_art."
                              "no_guide_access(); it raises GuideAccess on any attempt "
                              "to open a reference image and records what was opened",
        "guarded_entry_points": ["builtins.open", "io.open", "io.open_code",
                                 "bpy.data.images.load"],
    }


# ===========================================================================
# 2.  Card, layout and colour - study sections 4, 5 and 6
# ===========================================================================

CARD_W_MM = 70.0
CARD_H_MM = 162.29
#: REFERENCE_SPEC row 23 / worklist 21.  The first build read 7.6 mm off a
#: departure-threshold measurement that over-measures the bevel; fitting a line to the
#: bevel itself and intersecting it with the two straight edges gives 8.10 mm on V1 and
#: 7.97 on V2, and the ink pass got 8.09 / 7.96 independently.  8.05 is the adopted
#: figure.  ``props_lib.spec.CardSpec.corner_clip_mm`` carries the same number and
#: ``measure.corner_clip_agrees`` asserts the two have not drifted apart.
CORNER_CLIP_MM = 8.05          # 45 deg, four corners


def P(xf: float, yf: float) -> tuple[float, float]:
    """Card fraction -> card millimetres (x from the left, y from the top)."""
    return xf * CARD_W_MM, yf * CARD_H_MM


def to_px(path_mm, cfg) -> np.ndarray:
    """Card millimetres -> raster pixels.

    The island carries ``cfg.pad_mm`` of padding on every side so the bake has somewhere
    to bleed, and this is the ONE place that offset is applied.  Every element is drawn
    in plain card millimetres and never has to know the padding exists.
    """
    return (np.asarray(path_mm, np.float64) + cfg.pad_mm) * cfg.px


def mm_grid(cfg, H: int, W: int):
    """(y_mm, x_mm) broadcastable grids in card millimetres, padding removed."""
    yy = (np.arange(H, dtype=np.float32)[:, None] + 0.5) / cfg.px - cfg.pad_mm
    xx = (np.arange(W, dtype=np.float32)[None, :] + 0.5) / cfg.px - cfg.pad_mm
    return yy, xx


def raster_size(cfg) -> tuple[int, int]:
    W = int(round((CARD_W_MM + 2 * cfg.pad_mm) * cfg.px))
    H = int(round((CARD_H_MM + 2 * cfg.pad_mm) * cfg.px))
    return W, H


@dataclass(frozen=True)
class Layout:
    """Every position and size on the tag, in card millimetres.

    Fractions are study section 5, MEASURED from the guide unless that table says
    otherwise.  Where a number is ours rather than the study's it says so and why:
    those are composition decisions taken by LOOKING at the render, which is what the
    study asks for.
    """

    # --- frame -------------------------------------------------------------
    # REFERENCE_SPEC section 6: the frame RECTANGLE is already right to 0.05 mm.  These
    # four insets are NOT to be moved; the earlier "0.5 - 0.8 mm mis-set" reading came
    # from comparing two different tag-edge conventions.
    #: ...and these are now V1's OWN four insets to three decimals (section 3's table:
    #: L 4.033, R 4.090, T 6.675, B 7.240), which makes the frame rectangle exactly
    #: 61.877 x 142.085 by arithmetic instead of within a couple of tenths of it.  The
    #: second build's 3.9 / 4.1 / 6.8 / 7.4 measured 61.983 x 141.840 - inside its own
    #: 0.6 mm gate, but three times further off than section 6 recorded, and drift on a
    #: do-not-touch item is still drift.
    #: RG: L 3.748, R 3.873, T 6.518, B 7.241 mm (row 2).  Three of ours were
    #: already inside the +-0.25 mm the row allows; the left rule was +0.285 out,
    #: all four the same way.  Moving it also buys the left column the clearance
    #: its axis costs when it goes out to RG's 0.17884 W.
    rule_inset_left_mm: float = 3.800
    rule_inset_right_mm: float = 4.090
    rule_inset_top_mm: float = 6.675
    rule_inset_bottom_mm: float = 7.240
    #: REFERENCE_SPEC row 21 / worklist 18.  V1 measures 0.57 - 0.68 mm on the four
    #: sides; the 1.00 here was a "legibility" decision that made the card look printed.
    #: 0.60 drew 0.54 mean on our own half-width measure and 0.46 - 0.58 on an
    #: independent half-MAXIMUM one, i.e. the bottom rule fell under the 0.5 mm floor.
    #: The brush loses a little either side, so the nominal carries it.
    rule_weight_mm: float = 0.70
    #: REFERENCE_SPEC row 21: V1's four rules are NOT one weight.  Measured like for
    #: like they run left 0.681, right 0.592, top 0.578, bottom 0.607 mm - a 0.10 mm
    #: spread that a single nominal weight cannot reproduce, because the DRAWN to
    #: MEASURED ratio is different on each side of this sheet (0.88 / 0.96 / 1.08 /
    #: 0.71 at a nominal 0.70 mm): the top rule picks up its corner brackets inside the
    #: measuring band and the bottom rule sits in the edge-ageing band where the red
    #: classification loses its thinnest texels.  Round 3 shipped one nominal weight
    #: and measured 0.465 mm on the bottom rule against a 0.50 floor while its mean
    #: read 0.611.  Each side is now drawn at the weight that makes it MEASURE the
    #: reference's own figure for that side, in the order (left, right, top, bottom).
    #: ROUND 5.  Round 4 aimed the four sides at a MEAN and let the spread go: drawn
    #: (0.774, 0.614, 0.536, 0.860) measured (0.617, 0.602, 0.533, 0.774) on
    #: ``art_metrics.rules`` - a 0.241 mm spread against the same instrument's reading
    #: of V1 at (0.681, 0.592, 0.578, 0.607), spread 0.103, and with the pattern
    #: inverted (our top was our lightest where V1's top is heavier than its verticals).
    #: Each side is now aimed at V1's OWN figure for that side on that instrument,
    #: using the drawn-to-measured ratio this build measures for that side
    #: (0.797 / 0.980 / 0.995 / 0.900 - they differ because the top rule picks up its
    #: corner brackets inside the measuring band and the bottom sits in the edge-ageing
    #: band, where the red classification loses its thinnest texels).
    #:
    #: RE-DERIVED ONCE MORE, AND THIS IS WHY.  That aim was worked out from the ratios
    #: a build WITHOUT ``gap_floor`` measured, and ``gap_floor`` - the hairline round 5
    #: leaves down the spine of every break - raises the per-scanline MEDIAN the row is
    #: measured on.  Drawn at (0.854, 0.604, 0.581, 0.674) the sides came out at
    #: (0.773, 0.574, 0.603, 0.680), i.e. ratios of 0.905 / 0.950 / 1.038 / 1.009, and
    #: the left rule overshot far enough to put the left-right difference at 0.199 mm
    #: against a 0.15 mm tolerance - ``s21`` went red on a knob that was simply one
    #: iteration stale.  Each side is re-aimed at V1's own figure through the ratio
    #: this build measures with the floor in place.
    #: RE-AIMED AT THE REAL-GLYPH REFERENCE.  Every figure above is V1's.  RG's four
    #: rules measure, swept, L 0.679 / R 0.524 / T 0.468 / B 0.520 mm - a 0.21 mm
    #: spread with the LEFT clearly the heaviest and the TOP the lightest, where V1
    #: read 0.681 / 0.592 / 0.578 / 0.607 and looked nearly even.  The drawn-to-
    #: measured ratio this build shows with ``gap_floor`` in place is
    #: 0.823 / 0.989 / 0.950 / 0.894 (drawn 0.752/0.623/0.557/0.602 -> measured
    #: 0.619/0.616/0.529/0.538), and each side is aimed at RG's figure through its
    #: own ratio.  ``art_metrics`` gate s21 now also enforces the ORDERING: L must
    #: be 0.02 - 0.22 mm heavier than R, never the reverse, which is row 3's clause
    #: and which a symmetric tolerance could never say.
    #: AIMED SIDE BY SIDE, IN STAMPING ORDER, AND THAT ORDER MATTERS.  The six laps
    #: (top, bottom, left x2, right x2) share one RNG stream and ``brush_stroke``
    #: draws from it in proportion to the stroke's width, so changing one weight
    #: reshuffles every lap AFTER it - which is why two earlier passes watched the
    #: left and right medians swap places while the knobs moved smoothly.  Each side
    #: is therefore fixed in stamping order and the last one is aimed last.
    #: ROUND 7.  Re-aimed once more, because the rules are drawn as RG's runs now and a
    #: solid stroke measures differently from a dry one.  RG at its own grid, red
    #: first: left heaviest, then top and bottom, right lightest.
    rule_weight_side_mm: tuple[float, float, float, float] = (0.80, 0.62, 0.68, 0.68)
    inner_rule_offset_mm: float = 2.8       # where the corner brackets ride
    inner_rule_weight_mm: float = 0.50
    inner_rule_corner_run_mm: float = 24.0  # it starves away mid-span
    #: REFERENCE_SPEC row 4 / worklist 4.  BOTH guides have exactly ONE rule per side -
    #: verified twice in the spec, by peak-grouped occupancy runs and by the profile
    #: itself being flat zero from 5.0 mm inward.  Our second full-width rule on the top
    #: and bottom edges is the single thing that made the card read printed rather than
    #: brushed at thumbnail size.  EMPTY, and ``art_metrics.rules_per_side`` gates it.
    inner_rule_sides: tuple[str, ...] = ()
