    # --- text columns (study 5.3) ------------------------------------------
    # The study's 0.180 / 0.818 with a 14.4 mm em assumed the guide's narrow invented
    # marks.  MasaFont's real glyphs run about 1.30 em wide, so a 14.4 mm em draws
    # 18.6 mm of ink: at 0.180 that crossed the frame rule, and there is no column
    # centre on a 70 mm card at which 18.6 mm of ink clears both the bracket at 6.95 mm
    # and the flame emblem.  The em comes down until the ink fits the slot with a
    # millimetre each side, and the columns centre in the slot they actually have.
    # REFERENCE_SPEC rows 5, 6 and 12, in that order - section 2 is explicit that the
    # glyphs grow FIRST (which closes the leading for free, because our column PITCH is
    # already right) and the axes move out SECOND.  The reference's column cells are
    # 13.9 mm wide on average (14.6 max) against our 9.53, and its characters TOUCH
    # (leading 0.00 - 0.49 mm) where ours were 2.2 - 5.8 mm apart.
    #: RE-MEASURED.  The axes are stated at 0.1900 / 0.8160 W (13.30 / 57.12 mm) with a
    #: +-0.7 mm tolerance, and the SAME row says each block's outer edge must sit
    #: 1.0 - 2.2 mm inboard of its own rule.  On the reference's own figures - 13.9 mm
    #: cells, rules at 4.03 and 65.91 - those two clauses do not both hold: 13.30 - 6.95
    #: is 6.35, which is 2.32 mm inboard of the left rule and outside its own tolerance.
    #: Both clauses ARE satisfiable together a third of a millimetre outboard of the
    #: stated axes, so that is where they sit: -0.35 / +0.33 mm, half the axis tolerance,
    #: and the clearance comes out 2.07 / 1.55 mm.  Section 5's warning applies - the
    #: axis figure and the clearance figure were taken by different passes.
    #: RE-MEASURED ON RG: the two upper axes are 0.17884 W (12.52 mm) and 0.80882 W
    #: (56.62 mm), both further OUTBOARD than the 0.1900 / 0.8160 V1 gave.  The left
    #: rule moves out with it (``rule_inset_left_mm``) so the clearance clause and
    #: the axis clause hold together, which on V1's figures they could not.
    col_upper_left_x: float = 0.17884          # 12.52 mm
    #: +0.26 mm outboard of RG's own 0.80882, and the reason is honest rather than
    #: cosmetic: RG's upper-right BLOCK is 16.08 mm wide (its three glyphs run 15.57
    #: / 11.74 / 14.55 and sit on slightly different axes) where ours, fitted to one
    #: common cell, draws 14.33.  On RG's axis that narrower block leaves 2.11 mm of
    #: air to the right rule against the 0.99 the reference leaves.  Until the
    #: columns are set per glyph rather than per cell, the axis carries the
    #: difference - 0.26 mm, half the row's own tolerance.  Named in the known gaps.
    col_upper_right_x: float = 0.81180         # 56.83 mm
    #: row 5: the guide's three-glyph cells are 13.9 mm mean and 14.6 mm MAXIMUM, i.e.
    #: every character is fitted to one cell.  A common EM is not that - at 17.3 mm of em
    #: MasaFont drew 爆 at 16.54 mm and 炎 at 11.92 - so the columns are set to a CELL and
    #: ``_glyph_cov(fit_cell_mm=...)`` splits the fit between the two axes.  The drawn
    #: raster comes out about 0.4 mm narrower and shorter than the nominal cell, which is
    #: the brush, so the nominal carries it: 14.2 nominal draws ~13.8 mm of ink.
    col_upper_cell_mm: tuple[float, float] = (14.20, 13.85)
    #: RG's six upper glyph centres, averaged across the two columns:
    #: left 0.10902 / 0.19074 / 0.27350, right 0.10386 / 0.18977 / 0.27141.
    col_upper_y: tuple[float, float, float] = (0.10644, 0.19026, 0.27246)
    #: section 6: our lower columns are ALREADY in the right place (焼尽 at 56.7 - 57.8
    #: against 57.3 - 57.6) and the second build let this one drift outboard to 58.00,
    #: leaving 0.27 mm between its ink and the right rule.  57.20 nominal measures ~57.5
    #: on the raster and clears the rule by ~1.4 mm.
    #: RG: 0.82539 W = 57.78 mm, and its own block clears the right rule by 0.99 mm.
    col_lower_right_x: float = 0.82539         # 57.78 mm
    #: row 5: the guide's 焼尽 cell is 14.0 mm.
    #: THIRD BUILD, THE COLLISION.  The second build's two cells sat at 102.49 and
    #: 115.13 mm with a 12.49 mm cell, i.e. the first one spanned y 96.2 - 108.7 - and
    #: 爆's own ink reaches y 104.  The column's first character landed INSIDE the hero
    #: glyph and joined it through ~0.3 mm of ink, so the raster read one 57.29 mm-tall
    #: composite where row 2 specifies a 52.38 mm character, the lower-right column
    #: showed one measurable cell instead of two, and section 7's "does 爆 read as ONE
    #: character" was answered no.  V2 is authoritative for a text slot and puts the
    #: column at y 98.7 - 125.4; V1 puts it at 100.4 - 121.2.  The cells move DOWN onto
    #: V2's placement and shrink a little in height, which also brings the widest raster
    #: cell back from 14.40 toward the reference's 14.0.  The remaining interpenetration
    #: - the reference has it too - is handled by ``column_centre_clear_mm``.
    #: row 58 again: RG's pitch here is 13.02 mm with glyph heights 13.78 and 14.04,
    #: so they touch.  An 11.95 mm cell left 1.37 mm of air.
    col_lower_right_cell_mm: tuple[float, float] = (14.10, 13.10)
    #: RG's two lower-right glyph centres: 0.68399 and 0.76422.
    col_lower_right_y: tuple[float, float] = (0.68399, 0.76422)
    col_lower_centre_x: float = 0.50215        # RG
    #: row 5: the guide's 瞬業 cell is 12.6 mm.
    #: row 58: RG's two lower-centre glyphs TOUCH - pitch 16.538 mm with glyph
    #: heights 15.32 and 18.12.  At a 14.75 mm cell ours left a 2.02 mm gap, which
    #: is the single widest leading on the card and the one that reads as typeset.
    col_lower_centre_cell_mm: tuple[float, float] = (13.00, 16.60)
    #: V2 is authoritative for a text slot: its 瞬業 ink runs 110.3 - 142.4 mm.
    #: RG's two lower-centre glyph centres: 0.75578 and 0.85769.
    col_lower_centre_y: tuple[float, float] = (0.75578, 0.85769)
    #: NEW, THIRD BUILD.  The paper a column character leaves round the hero glyph.
    #: Both guides interpenetrate 爆's box with the lower-right column and neither
    #: TOUCHES it: V1's nearest ink between the two is clear paper.  Ours welded.  The
    #: centre glyph is built first, dilated by this, and the columns are clipped out of
    #: it - so a column stroke passes behind 爆 with a hair of paper showing, which is
    #: what the guides do and what makes the raster count them as separate marks.
    column_centre_clear_mm: float = 3.90
    column_centre_fade_mm: float = 1.50
    #: ROUND 6, REFERENCE_SPEC row 31.  The clear paper the HERO leaves round the
    #: lower-right column's first cell, and the width of the band over which its last
    #: stroke is lifted to make it.  See ``_hero_clearance``: the reference leaves
    #: 5.99 mm of paper between 爆 and 焼 on a true 2-D measure and ours left 2.0.
    centre_column_clear_mm: float = 4.80
    centre_column_fade_mm: float = 2.00
    #: ROUND 6.  The four column blocks, measured on the reference of record inside
    #: the same fractional windows, carry 229.6 / 241.4 / 143.0 / 187.7 mm2 of ink
    #: against our 178.2 / 187.5 / 100.5 / 146.0 - 29 / 29 / 42 / 29 % short - in
    #: boxes whose x and y extents agree to a third of a millimetre.  The reference's
    #: blocks also hold together as 2 - 4 pieces where ours broke into 7 - 10, which
    #: is the same fact seen from the other end: the parts of a glyph that vanish
    #: first are the hairline joins.  One fuller brush per block, in the order
    #: (upper_left, upper_right, lower_right, lower_centre); see ``_fatten``.
    #: ROUND 7: UL / UR / LR / LC re-aimed at RG's block ink through the build's own
    #: windows (229.6 / 241.4 / 143.0 / 187.7 mm2); round 6 drew 0.88 / 0.84 / 0.67 / 0.88.
    column_brush_mm: tuple[float, float, float, float] = (0.350, 0.410, 0.720, 0.330)
    #: the small chop's two characters take a lighter one - they are 6 mm tall and a
    #: quarter of a millimetre all round would close them up.
    small_seal_brush_mm: float = 0.11
    #: ``_fatten``: enclosed paper at least this big is a COUNTER and keeps a spine of
    #: paper ``glyph_counter_gap_mm`` wide down its middle; anything smaller is a
    #: hairline JOIN and a loaded brush floods it.  Without this the column 爆's 日
    #: closed up and the block read as a blot while measuring the reference's own ink.
    #: ROUND 7: 0.90 / 0.20 let the fuller brush flood the narrow channels between
    #: 業's bars, which RG keeps open; 0.45 / 0.30 keeps them.
    glyph_counter_mm2: float = 0.45
    glyph_counter_gap_mm: float = 0.30
    #: ``_fatten`` taper: 0 grows every edge alike, 1 grows only the bellies.  The
    #: reference's column strokes enter fat and leave in a point; a flat growth made
    #: ours end in rounded clubs.
    glyph_brush_taper: float = 0.35
    #: the hero is written with a much bigger brush than a column glyph, and its
    #: strokes are 2 mm wide rather than 1, so a thickness-weighted growth there only
    #: starves the radical it is meant to load.  Flat.
    centre_brush_taper: float = 0.0

    # --- seal boxes (study 5.4) --------------------------------------------
    # REFERENCE_SPEC section 6: both seal FRAME boxes are already within 0.4 mm.  What
    # was wrong is the ink: row 20 says our chop's outline rule draws at 0.45 mm where
