    big_seal_frame_y: tuple[float, float] = (0.75587, 0.92409)
    big_seal_rule_mm: float = 1.35
    #: RG row 62: the solid panel is 12.26 x 21.19 mm, x 8.463 - 20.717,
    #: y 125.595 - 146.781.
    big_seal_panel_x: tuple[float, float] = (0.11243, 0.31129)
    big_seal_panel_y: tuple[float, float] = (0.76998, 0.90998)
    #: RG row 65: the small chop is 8.17 x 14.5 mm at (59.27, 143.8) - MUCH smaller
    #: than the 9.0 x 17.8 V1 gave, because V1's read swallowed the bottom-right
