    small_seal_frame_x: tuple[float, float] = (0.79014, 0.91057)
    small_seal_frame_y: tuple[float, float] = (0.84201, 0.93789)
    small_seal_rule_mm: float = 0.74
    #: row 19: the guide's 火道 set at an em of about 7.5 mm.  6.0 was chosen to keep a
    #: millimetre of air, and the result was a big weak box round small text.
    #: THIRD BUILD 7.5 -> 7.8: an em is not a visible quantity, and measured by direct
    #: extent our two glyphs drew 5.9 - 6.9 mm of ink against the row's 7.5 +- 0.7.  A
    #: slightly larger em closes the gap from both ends and stays inside the tolerance.
    #: RG row 68: about 5.5 - 6.5 mm per character inside a 6.9 x 13.3 mm panel.
    #: 7.7 was fitted to V1's oversized box and is a third too big for this one.
    small_seal_em_mm: float = 7.00
    small_seal_x: float = 0.85043              # RG, re-measured round 7
    #: row 19: the gap between the two glyphs measures 1.24 mm in the guide and 3.33 in
    #: the first build.  A 7.24 mm pitch measured 2.32 mm of ink gap against the row's
    #: 2.0 mm ceiling - the pitch is right for the EM and wrong for the INK, because
    #: MasaFont's 火 and 道 do not fill their em vertically.  6.55 mm about the box
