    #: the two glyph centres inside RG's own panel (y 137.59 - 150.87 mm).
    small_seal_y: tuple[float, float] = (0.86851, 0.90763)
    #: how far a stamped frame's brush may stray outside its own box, millimetres.  The
    #: first build let the wander and the ragged edge take it 1.0 - 2.0 mm past.
    #: THIRD BUILD 0.16 -> 0.06: the clip is applied in the STAMP's rotated frame, so a
    #: 1 deg rotation already adds ~0.47 mm to the axis-aligned box a measurement sees.
    #: Half a rule of bleed on top of that took the big chop's raster box 0.6 mm past
