    #: measuring the seal LAYER (18.32 x 27.12) reported as a pass.  A chop is stamped
    #: on a clear patch of paper; nothing else prints into it.
    seal_keepout_mm: float = 0.85

    # --- wear (study 6) -----------------------------------------------------
    fuse_point: tuple[float, float] = (0.500, 0.196)    # the Fuse socket, at the emblem
    crease_y: tuple[float, float] = (0.333, 0.667)
    crease_wander_mm: float = 1.5
    #: REFERENCE_SPEC row S8.  How far the hand-cut edge may wander INBOARD of the ideal
    #: octagon, in millimetres.  RG's own sides fit straight to rms 0.014 - 0.018 mm with
    #: a max departure of 0.033 - 0.044 mm; the row's tolerance is rms <= 0.05 and max
    #: <= 0.12.  0.08 keeps the drawn edge inside both while leaving the card a cut
    #: sheet rather than a ruled rectangle.  It was 0.20 - five times the reference's
    #: worst departure - which no gate looked at.
    edge_wobble_mm: float = 0.065
    # --- paper texture (REFERENCE_SPEC rows 86, 87, 88) ---------------------
    #: THE SHEET IS MUCH FINER AND MUCH FLATTER THAN WE HAD IT.  The old numbers came
    #: from a row that said "17 % amplitude on a 0.50 mm cell", which was measured with
    #: an INK-BLIND high-pass on the guide, so every stroke edge counted as fibre; the
    #: build then calibrated that away and landed on a 1.2 mm cell at 3.5 % p05-p95.
    #: Re-measured ink-aware, the reference's paper is 0.632 % std / 2.074 % p05-p95,
    #: cell 0.397 x 0.412 mm at anisotropy 1.037, with EVERY mottle band under 0.8 %.
    #: RG's 0.40 mm cell is its own Nyquist floor and HR puts the true fibre at
    #: 0.128 mm - finer than 1.6 px on our own 12.42 px/mm raster, so it is not
    #: reachable here and 0.40 is the honest aim: it is what a photograph of the sheet
    #: at the reference's sampling shows.
    grain_cell_mm: float = 0.150
    grain_micro_cell_mm: float = 0.09
    #: row 87: anisotropy 1.037 - the reference sheet is isotropic.  We had 1.12 drawn
    #: (1.22 measured) on the theory that a laid sheet's fibres follow the mould.  The
    #: reference does not show that, so it is not drawn.
    grain_aniso: float = 0.99
    grain_weight: float = 0.078
    grain_micro_weight: float = 0.030
    #: row 88: the sheet is essentially FLAT above the fibre.  The reference's banded
